//! Linked framing generated by ordinary canonical composition. The only
//! changing storage is one bounded output. No Plan, provider or authority.
use alloc::vec::Vec;
use conduit_core::{
    validate_canonical_structured_value as validate, Quantity, StructuredInfoRefusal as R,
    StructuredInfoType as Type, ValidatedCanonicalStructuredValue as Value,
};
mod material {
    include!(concat!(env!("OUT_DIR"), "/observation-material.rs"));
}
pub(super) struct QuantityTemplate<const RESULT: bool> {
    output: Vec<u8>,
}
impl<const RESULT: bool> QuantityTemplate<RESULT> {
    pub(super) fn prepare(expected: &Type) -> Result<Self, R> {
        let (template, maximum) = if RESULT {
            (material::RESULT, material::RESULT_MAXIMUM)
        } else {
            (material::OBSERVATION, material::OBSERVATION_MAXIMUM)
        };
        if validate(template)?.type_bytes() != expected.canonical_bytes()? {
            return Err(R::WrongType);
        }
        Ok(Self {
            output: Vec::with_capacity(maximum),
        })
    }
    pub(super) fn quantities(
        &mut self,
        temperature: Quantity,
        humidity: Quantity,
    ) -> Result<&[u8], R> {
        let (template, t, h) = if RESULT {
            (
                material::RESULT,
                material::RESULT_TEMPERATURE,
                material::RESULT_HUMIDITY,
            )
        } else {
            (
                material::OBSERVATION,
                material::OBSERVATION_TEMPERATURE,
                material::OBSERVATION_HUMIDITY,
            )
        };
        if template.len() > self.output.capacity() {
            return Err(R::CanonicalEncodingTooLarge);
        }
        self.output.clear();
        self.output.extend_from_slice(template);
        self.output[t].copy_from_slice(&temperature.encode());
        self.output[h].copy_from_slice(&humidity.encode());
        validate(&self.output)?;
        Ok(&self.output)
    }
    pub(super) fn unavailable(&mut self, failure: Value<'_>) -> Result<&[u8], R> {
        if !RESULT || failure.type_bytes() != material::FAILURE_TYPE {
            return Err(R::WrongType);
        }
        let bytes = failure.value_node();
        if material::UNAVAILABLE_PREFIX
            .len()
            .saturating_add(bytes.len())
            > self.output.capacity()
        {
            return Err(R::CanonicalEncodingTooLarge);
        }
        self.output.clear();
        self.output.extend_from_slice(material::UNAVAILABLE_PREFIX);
        self.output.extend_from_slice(bytes);
        validate(&self.output)?;
        Ok(&self.output)
    }
    pub(super) fn output(&self) -> &[u8] {
        &self.output
    }
}
